src = open('brute3.py').read()
start = src.index("    reach = {0: []}")
end = src.index("    for path, got in zip(rq['queries'], out['queries']):")
new = '''    # words reaching each state (BFS), to evaluate semantics
    reach = {0: []}
    dq = deque([0])
    while dq:
        q = dq.popleft()
        for c in range(sigma):
            t = nxt[q][c]
            if t not in reach:
                reach[t] = reach[q] + [c]
                dq.append(t)
    assert len(reach) == n, 'unreachable states'
    # graph distances to the nearest accepting state (independent reverse BFS)
    rev = [[] for _ in range(n)]
    for q in range(n):
        for t in nxt[q]:
            rev[t].append(q)
    gd = [None] * n
    dq = deque()
    for q in range(n):
        if acc[q]:
            gd[q] = 0
            dq.append(q)
    while dq:
        u = dq.popleft()
        for p in rev[u]:
            if gd[p] is None:
                gd[p] = gd[u] + 1
                dq.append(p)
    assert gd == dist, ('distance graph mismatch', gd[:20], dist[:20])
    # semantic checks on a sample of states
    sample = sorted(set([0, n - 1] + [rnd.randrange(n) for _ in range(40)]))
    for q in sample:
        u = [services[i] for i in reach[q]]
        d = dist[q]
        assert acc[q] == member(rules, u), ('state accept', u)
        if d is None:
            for _ in range(20):
                L = rnd.randint(0, 14)
                v = [rnd.choice(services) for _ in range(L)] if services else []
                assert not member(rules, u + v), ('dead state accepts', u, v)
        else:
            assert type(d) is int and d >= 0
            if d == 0:
                assert member(rules, u)
                continue
            # shortest accepting walk inside the DFA, verified semantically
            depth = {q: 0}
            parent = {q: None}
            dq = deque([q])
            target = None
            while dq:
                s = dq.popleft()
                if acc[s]:
                    target = s
                    break
                for c in range(sigma):
                    t = nxt[s][c]
                    if t not in depth:
                        depth[t] = depth[s] + 1
                        parent[t] = (s, c)
                        dq.append(t)
            assert target is not None and depth[target] == d, ('dist', q, d)
            path = []
            s = target
            while parent[s] is not None:
                s, c = parent[s]
                path.append(c)
            path.reverse()
            assert len(path) == d
            assert member(rules, u + [services[i] for i in path]), 'dist path'
            for _ in range(20):
                L = rnd.randint(0, d - 1)
                v = [rnd.choice(services) for _ in range(L)] if services else []
                assert not member(rules, u + v), ('shorter accept', u, v)
'''
src = src[:start] + new + src[end:]
open('brute3.py','w').write(src)
